import{z as o,x as d,o as r,c as A,q as l,j as s,D as E,d as B,s as t,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"线路编码 4B/5B、8B/10B","description":"","frontmatter":{"title":"线路编码 4B/5B、8B/10B","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/line-coding.md","filePath":"cs/line-coding.md","lastUpdated":1791063341000}'),p={name:"cs/line-coding.md"};function m(c,a,C,D,h,u){const i=d("Mermaid");return r(),A("div",null,[a[2]||(a[2]=l('<h1 id="线路编码-4b-5b、8b-10b" tabindex="-1">线路编码 4B/5B、8B/10B <a class="header-anchor" href="#线路编码-4b-5b、8b-10b" aria-label="Permalink to &quot;线路编码 4B/5B、8B/10B&quot;">​</a></h1><div class="epigraph"><p>线路码先换一组有足够跳变、直流近零的符号，再上调制；净荷比特率因此永远低于毛符号率。</p><footer>—— 据 Widmer and Franaszek, 8B/10B, IBM J. R&amp;D 1983；IEEE 802.3 100BASE-X / 1000BASE-X 整理</footer></div><p><a href="/cs/modulation-symbol-rate">上一课</a>把比特率写成 \\(R_s\\log_2 M\\)。长串 0/1 让基线漂移、时钟丢失。缺口是<strong>线路编码</strong>：4B/5B、8B/10B（以及后课扰码）用查表换冗余，换跳变与游程上界。本课不把 CDR 环路写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NRZ 遇到五十个连续 1，接收机分不清边界。4B/5B（百兆光纤）：4 比特映 5 比特，禁止过长连 0。8B/10B：8 比特映 10 比特，控制 disparity 使直流平衡，并保留逗号符号做字对齐。开销 25% 或 20%，毛速率必须高于净荷——这是 \\(C\\) 预算里先扣掉的一笔，不是 MAC 层的帧间隔。</p><p>以太网 64B/66B（10G 起）改用扰码加同步头，开销降到约 3%，对象仍是「可恢复的比特流」，机制下一课。</p><p><span class="marginnote">8B/10B 亦用于 Fibre Channel、PCI Express 早期代次。控制字符（K 码）不是用户数据。本课不把全部码表背完。</span></p><p><span class="marginnote">数字实例：4B/5B 每 4 比特发 5 比特，开销 25%——要在光纤上传 100 Mbps 净荷，毛符号率就得是 125 Mbaud，这正是百兆以太网规格里「125M」的来历；8B/10B 开销 20%，千兆链路毛速率 1.25 GBaud。</span></p><p><span class="marginnote">「逗号符号（comma）」就是收发双方约定好、正常数据里不会出现的特殊比特图案。接收端在比特流里找到它，就知道「这里是 10 比特码字的边界」——像逗号把连续字符流切成字。必须先对齐再解码，顺序不能反。</span></p><h3 id="线路码不是压缩" tabindex="-1">线路码不是压缩 <a class="header-anchor" href="#线路码不是压缩" aria-label="Permalink to &quot;线路码不是压缩&quot;">​</a></h3><p>映射公开且膨胀比特，目的是跳变与对齐。非法码字可在 PCS 早检，仍不替代帧 FCS。10G 以后的低开销块码把同一职责部分交给扰码。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发送：MAC 字节 → 块编码 → 再 PAM/串行。接收：10 比特窗找逗号对齐，再逆映射。错误：非法码字可在 PCS 检出，早于 FCS。对照：FCS 管一帧；线路码管符号流的局部合法性。</p>',13)),(r(),s(n,null,{default:E(()=>[t(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22MAC%20%E5%AD%97%E8%8A%82%22%5D%20--%3E%20BLK%5B%224B%2F5B%20%E6%88%96%208B%2F10B%22%5D%0A%20%20BLK%20--%3E%20SER%5B%22%E4%B8%B2%E8%A1%8C%E4%B8%8E%E8%B0%83%E5%88%B6%22%5D%0A%20%20SER%20--%3E%20ALN%5B%22%E9%80%97%E5%8F%B7%E5%AF%B9%E9%BD%90%22%5D%0A%20%20ALN%20--%3E%20INV%5B%22%E9%80%86%E6%98%A0%E5%B0%84%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[B("主干"),e("a",{href:"/cs/frame-crc"},"帧 CRC"),B("假定已有比特边界。边界来自本课的跳变与逗号。交换机看到的是解码后的帧；PCS 错误可能在到达 MAC 之前就把链路标为 down。容量课的冗余在这里具体化为固定比例的块编码，不是随机码。")],-1)),a[5]||(a[5]=e("p",null,"disparity：8B/10B 在两种 10 比特表示间切换，使游程与直流可约束。这是链路局部状态，不进入 IP。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者以为这 20-25% 开销是浪费。没有它，长串 0 会让接收端时钟漂走、直流基线漂移，误码率暴涨；花 25% 带宽把「根本读不出来的数据」变成「读得出来的数据」，是链路层最划算的交易之一。")],-1)),(r(),s(n,null,{default:E(()=>[t(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%228%20%E6%AF%94%E7%89%B9%E5%AD%97%E8%8A%82%22%5D%20--%3E%20ENC%5B%22%E6%9F%A5%E8%A1%A8%E5%BE%97%E5%80%99%E9%80%89%2010%20%E6%AF%94%E7%89%B9%E7%A0%81%E5%AD%97%22%5D%0A%20%20ENC%20--%3E%20D%7B%22%E5%BD%93%E5%89%8D%20running%20disparity%20%E7%8A%B6%E6%80%81%EF%BC%9F%22%7D%0A%20%20D%20--%20%22%E4%B8%BA%E6%AD%A3%3A%201%20%E5%81%8F%E5%A4%9A%22%20--%3E%20P%5B%22%E9%80%89%200%20%E5%81%8F%E5%A4%9A%E7%9A%84%E7%A0%81%E5%AD%97%22%5D%0A%20%20D%20--%20%22%E4%B8%BA%E8%B4%9F%3A%200%20%E5%81%8F%E5%A4%9A%22%20--%3E%20N%5B%22%E9%80%89%201%20%E5%81%8F%E5%A4%9A%E7%9A%84%E7%A0%81%E5%AD%97%22%5D%0A%20%20P%20--%3E%20UP%5B%22%E6%9B%B4%E6%96%B0%20disparity%20%E4%BC%A0%E7%BB%99%E4%B8%8B%E4%B8%80%E7%A0%81%E5%AD%97%22%5D%0A%20%20N%20--%3E%20UP%0A%20%20UP%20--%3E%20OUT%5B%22%E4%B8%B2%E8%A1%8C%E5%8F%91%E9%80%81%20%E7%9B%B4%E6%B5%81%E4%BF%9D%E6%8C%81%E8%BF%91%E9%9B%B6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 256B/257B 与 RS-FEC 的交织细节（25G+）。时钟恢复与扰码是下一课。后课默认：净荷速率 = 毛速率 × 块码率；逗号用于字同步。</p><p>线路码不是加密，也不是压缩：映射公开，且膨胀比特。</p><p>下一课<a href="/cs/clock-recovery-scrambling">时钟恢复与扰码</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>4B/5B、8B/10B 用开销换跳变、直流平衡与对齐。</li><li>非法码字可在 PCS 早检；不替代 FCS。</li><li>净荷永远低于毛符号率。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Widmer–Franaszek, 1983；IEEE 802.3。</li></ul>',6))])}const F=o(p,[["render",m]]);export{f as __pageData,F as default};
